// ModeInstruction.values contains the requested per-phase power values.
// The My-PV endpoint accepts one total power value, so sum all phases.
const rawValues = msg.payload?.values
const phaseValues = Array.isArray(rawValues) ? rawValues : [rawValues ?? 0]
const powerSetpoint = phaseValues.reduce(
    (sum, value) => sum + (Number(value) || 0),
    0
)

const now = Date.now()

// Keep the original S2 mode instruction on this message. The response handler
// uses its presence to distinguish a real S2 instruction from a heartbeat.
msg.modeConfirmationPayload = { ...msg.payload }
msg.payload = powerSetpoint

// Always remember the latest requested S2 setpoint, even while the My-PV
// device is switched off. This lets control resume with the newest request
// after devmode returns to 1.
flow.set('mypv_setpoint', {
    power: powerSetpoint,
    lastUpdated: now,
    lastSent: now
})

const setup = flow.get('mypv_setup') || {}
const deviceOff = Number(setup.devmode ?? 1) === 0

// devmode = 0 means the My-PV device is switched off. Do not send any
// control.html request while it is off. The S2 instruction remains stored,
// but it is intentionally not confirmed because the device did not receive it.
if (deviceOff) {
    node.status({
        shape: 'ring',
        fill: 'grey',
        text: 'Device off (devmode 0); setpoint stored'
    })
    return null
}

node.status({
    shape: 'dot',
    fill: 'blue',
    text:
        (msg.modeConfirmationPayload.label || 'Mode') +
        ' | Factor ' +
        (msg.modeConfirmationPayload.factor ?? 1) +
        ' | Total: ' +
        powerSetpoint +
        ' W'
})

return msg

const COMMUNICATION_TIMEOUT_MS = 30000

const now = Date.now()
const requestSucceeded =
    !msg.error &&
    Number(msg.statusCode) >= 200 &&
    Number(msg.statusCode) < 300

// Send zero, one, or multiple messages through this function node's single output.
function sendMessages(messages) {
    if (messages.length === 0) return null
    if (messages.length === 1) return messages[0]
    return [messages]
}

// The device is considered switched off when devmode is explicitly 0.
// Before setup.jsn has been read, devmode defaults to 1.
function isDeviceOff() {
    const setup = flow.get('mypv_setup') || {}
    return Number(setup.devmode ?? 1) === 0
}

// Communication health is shared across all My-PV HTTP endpoints.
// A success on any endpoint refreshes mypv_last_comm_success. Until the first
// success, mypv_comm_watch_started provides the same 30-second startup grace.
function communicationTimedOut(time) {
    let reference = Number(flow.get('mypv_last_comm_success'))

    if (!Number.isFinite(reference) || reference <= 0) {
        reference = Number(flow.get('mypv_comm_watch_started'))

        if (!Number.isFinite(reference) || reference <= 0) {
            reference = time
            flow.set('mypv_comm_watch_started', reference)
        }
    }

    return time - reference >= COMMUNICATION_TIMEOUT_MS
}

const previousCommunicationDisabled = flow.get('mypv_ombc_disabled') === true
const temperatureBlocked = flow.get('mypv_temperature_blocked') === true
const deviceOff = isDeviceOff()
const advertisedOff = flow.get('mypv_control_advertised_off') === true
const output = []

if (requestSucceeded) {
    // Any successful My-PV HTTP request proves that the device is reachable.
    // Refresh the one shared communication-health timestamp immediately.
    flow.set('mypv_last_comm_success', now)
    flow.set('mypv_comm_watch_started', now)
    flow.set('mypv_ombc_disabled', false)

    // Keep the heartbeat timestamp synchronized with the completed SET request.
    const storedSetpoint = flow.get('mypv_setpoint')
    if (storedSetpoint && typeof storedSetpoint === 'object') {
        storedSetpoint.lastSent = now
        flow.set('mypv_setpoint', storedSetpoint)
    }

    // OMBC must remain unavailable while either the temperature gate is active
    // or the My-PV device itself is switched off (devmode = 0).
    const controlBlocked = temperatureBlocked || deviceOff

    // Advertise a control-state transition only when the state actually changes.
    if (controlBlocked && !advertisedOff) {
        flow.set('mypv_control_advertised_off', true)
        output.push({
            topic: 'ControlTypes',
            payload: { isControllable: false }
        })
    } else if (!controlBlocked && advertisedOff) {
        flow.set('mypv_control_advertised_off', false)
        output.push({
            topic: 'ControlTypes',
            payload: { isControllable: true }
        })
    }

    // Only a real S2 ModeInstruction carries modeConfirmationPayload.
    // Periodic heartbeat requests deliberately remove this property, so a
    // successful heartbeat never creates a ModeConfirmation.
    if (
        msg.modeConfirmationPayload !== undefined &&
        msg.modeConfirmationPayload !== null
    ) {
        output.push({
            topic: 'ModeConfirmation',
            payload: msg.modeConfirmationPayload
        })
    }

    node.status({
        shape: 'dot',
        fill: deviceOff ? 'grey' : temperatureBlocked ? 'yellow' : 'green',
        text: deviceOff
            ? 'SET OK; device off (devmode 0)'
            : temperatureBlocked
              ? 'SET OK; temperature gate active'
              : 'My-PV setpoint OK'
    })

    return sendMessages(output)
}

// A failed SET request is tolerated as long as some My-PV HTTP request has
// succeeded within the last 30 seconds. This makes occasional ECONNREFUSED
// responses harmless while still detecting a genuinely unreachable device.
const communicationDisabled = communicationTimedOut(now)
flow.set('mypv_ombc_disabled', communicationDisabled)

const controlBlocked =
    communicationDisabled ||
    temperatureBlocked ||
    deviceOff

if (controlBlocked && !advertisedOff) {
    flow.set('mypv_control_advertised_off', true)
    output.push({
        topic: 'ControlTypes',
        payload: { isControllable: false }
    })
} else if (!controlBlocked && advertisedOff) {
    // Another endpoint may have refreshed the shared communication timestamp
    // since the previous SET attempt, so allow this path to advertise recovery.
    flow.set('mypv_control_advertised_off', false)
    output.push({
        topic: 'ControlTypes',
        payload: { isControllable: true }
    })
}

if (communicationDisabled && !previousCommunicationDisabled) {
    node.warn('No successful My-PV communication for 30 seconds; OMBC disabled')
}

const reference =
    Number(flow.get('mypv_last_comm_success')) ||
    Number(flow.get('mypv_comm_watch_started')) ||
    now
const secondsWithoutSuccess = Math.max(0, Math.floor((now - reference) / 1000))

node.status({
    shape: 'ring',
    fill: communicationDisabled ? 'red' : deviceOff ? 'grey' : 'yellow',
    text: communicationDisabled
        ? 'My-PV offline for 30+ s; OMBC off'
        : deviceOff
          ? 'Device off (devmode 0); OMBC off'
          : 'SET refused; last communication ' + secondsWithoutSuccess + ' s ago'
})

// Never confirm an S2 mode when the device did not accept the SET request.
return sendMessages(output)

const COMMUNICATION_TIMEOUT_MS = 30000

const now = Date.now()
const requestSucceeded =
    !msg.error &&
    Number(msg.statusCode) >= 200 &&
    Number(msg.statusCode) < 300

// Mark every completed data.jsn request, including failed requests. The
// heartbeat function uses this marker to wait until the current telemetry
// request has finished before it sends a SET request.
const completedDataCycle = (Number(flow.get('mypv_data_cycle')) || 0) + 1
flow.set('mypv_data_cycle', completedDataCycle)
flow.set('mypv_last_data_completion', now)

const numberOrZero = value =>
    Number.isFinite(Number(value)) ? Number(value) : 0

// The device is considered switched off when devmode is explicitly 0.
// Before setup.jsn has been read, devmode defaults to 1.
function isDeviceOff() {
    const setup = flow.get('mypv_setup') || {}
    return Number(setup.devmode ?? 1) === 0
}

// Communication health is shared across data.jsn, control.html and setup.jsn.
// Until the first successful request, allow the device a 30-second startup grace.
function communicationTimedOut(time) {
    let reference = Number(flow.get('mypv_last_comm_success'))

    if (!Number.isFinite(reference) || reference <= 0) {
        reference = Number(flow.get('mypv_comm_watch_started'))

        if (!Number.isFinite(reference) || reference <= 0) {
            reference = time
            flow.set('mypv_comm_watch_started', reference)
        }
    }

    return time - reference >= COMMUNICATION_TIMEOUT_MS
}

// A successful HTTP exchange proves that the My-PV HTTP server is reachable.
// Refresh the shared timestamp before parsing the payload; malformed telemetry
// is a data-quality problem, not a communication outage.
if (requestSucceeded) {
    flow.set('mypv_last_comm_success', now)
    flow.set('mypv_comm_watch_started', now)
    flow.set('mypv_ombc_disabled', false)
}

let deviceData = null

if (requestSucceeded) {
    try {
        // The HTTP node returns text. Parse it here so malformed responses are
        // handled cleanly without creating parser warnings.
        deviceData =
            typeof msg.payload === 'string'
                ? JSON.parse(msg.payload)
                : msg.payload
    } catch (error) {
        deviceData = null
    }
}

if (!requestSucceeded || !deviceData || typeof deviceData !== 'object') {
    const previousCommunicationDisabled = flow.get('mypv_ombc_disabled') === true
    const communicationDisabled = communicationTimedOut(now)
    flow.set('mypv_ombc_disabled', communicationDisabled)

    const temperatureBlocked = flow.get('mypv_temperature_blocked') === true
    const deviceOff = isDeviceOff()
    const controlBlocked =
        communicationDisabled ||
        temperatureBlocked ||
        deviceOff
    const advertisedOff = flow.get('mypv_control_advertised_off') === true

    if (communicationDisabled && !previousCommunicationDisabled) {
        node.warn('No successful My-PV communication for 30 seconds; OMBC disabled')
    }

    const reference =
        Number(flow.get('mypv_last_comm_success')) ||
        Number(flow.get('mypv_comm_watch_started')) ||
        now
    const secondsWithoutSuccess = Math.max(
        0,
        Math.floor((now - reference) / 1000)
    )

    node.status({
        shape: 'ring',
        fill: communicationDisabled ? 'red' : deviceOff ? 'grey' : 'yellow',
        text: communicationDisabled
            ? 'My-PV offline for 30+ s; OMBC off'
            : deviceOff
              ? 'Device off (devmode 0); OMBC off'
              : 'data.jsn error; last communication ' +
                secondsWithoutSuccess +
                ' s ago'
    })

    // Keep the advertised S2 state synchronized with the combined communication,
    // temperature and devmode state. A success on another endpoint may have
    // restored communication even though this particular data.jsn request failed.
    if (controlBlocked && !advertisedOff) {
        flow.set('mypv_control_advertised_off', true)
        return {
            topic: 'ControlTypes',
            payload: { isControllable: false }
        }
    }

    if (!controlBlocked && advertisedOff) {
        flow.set('mypv_control_advertised_off', false)
        return {
            topic: 'ControlTypes',
            payload: { isControllable: true }
        }
    }

    return null
}

// Store the latest valid telemetry for the measurement and indicator paths.
flow.set('mypv_data', deviceData)
flow.set('mypv_last_data_success', now)
flow.set('mypv_ombc_disabled', false)

const setup = flow.get('mypv_setup') || {}
const deviceOff = Number(setup.devmode ?? 1) === 0
const temperature = numberOrZero(deviceData.temp1) / 10
const targetTemperature = Number(setup.ww1target) / 10
const hysteresis = Math.max(0, Number(setup.ww_targ_h) / 10 || 0)

// Apply hysteresis so control does not rapidly toggle around the target.
let temperatureBlocked = flow.get('mypv_temperature_blocked') === true
if (Number.isFinite(targetTemperature)) {
    if (temperatureBlocked) {
        if (temperature < targetTemperature - hysteresis) {
            temperatureBlocked = false
        }
    } else if (temperature >= targetTemperature) {
        temperatureBlocked = true
    }

    flow.set('mypv_temperature_blocked', temperatureBlocked)
}

const l1Power =
    numberOrZero(deviceData.power1_solar) +
    numberOrZero(deviceData.power1_grid)
const l2Power =
    numberOrZero(deviceData.power2_solar) +
    numberOrZero(deviceData.power2_grid)
const l3Power =
    numberOrZero(deviceData.power3_solar) +
    numberOrZero(deviceData.power3_grid)

const measurement = {
    topic: 'PowerMeasurement',
    payload: { values: [l1Power, l2Power, l3Power] }
}

const controlBlocked = temperatureBlocked || deviceOff
const advertisedOff = flow.get('mypv_control_advertised_off') === true

// Send ControlTypes only when the advertised state actually changes.
if (controlBlocked && !advertisedOff) {
    flow.set('mypv_control_advertised_off', true)

    node.status({
        shape: 'ring',
        fill: deviceOff ? 'grey' : 'yellow',
        text: deviceOff
            ? 'Device off (devmode 0); OMBC off'
            : 'Temperature high; OMBC off'
    })

    return [[
        { topic: 'ControlTypes', payload: { isControllable: false } },
        measurement
    ]]
}

if (!controlBlocked && advertisedOff) {
    flow.set('mypv_control_advertised_off', false)

    node.status({
        shape: 'dot',
        fill: 'green',
        text: 'My-PV available; OMBC enabled'
    })

    return [[
        { topic: 'ControlTypes', payload: { isControllable: true } },
        measurement
    ]]
}

node.status({
    shape: 'dot',
    fill: deviceOff ? 'grey' : temperatureBlocked ? 'yellow' : 'blue',
    text: deviceOff
        ? 'Device off (devmode 0); OMBC off'
        : temperatureBlocked
          ? 'Temperature high; OMBC off'
          : 'Reported power: ' +
            [l1Power, l2Power, l3Power].join(', ') +
            ' W'
})

return measurement

const COMMUNICATION_TIMEOUT_MS = 30000

const now = Date.now()
const requestSucceeded =
    !msg.error &&
    Number(msg.statusCode) >= 200 &&
    Number(msg.statusCode) < 300

// Communication health is shared by all My-PV HTTP endpoints:
//   - data.jsn
//   - control.html
//   - setup.jsn
//
// OMBC is considered unavailable only when NONE of these endpoints has
// communicated successfully for 30 seconds. Until the first successful request,
// mypv_comm_watch_started provides the same 30-second startup grace period.
function communicationTimedOut(time) {
    let reference = Number(flow.get('mypv_last_comm_success'))

    if (!Number.isFinite(reference) || reference <= 0) {
        reference = Number(flow.get('mypv_comm_watch_started'))

        if (!Number.isFinite(reference) || reference <= 0) {
            reference = time
            flow.set('mypv_comm_watch_started', reference)
        }
    }

    return time - reference >= COMMUNICATION_TIMEOUT_MS
}

// Return whether the device is explicitly switched off.
// devmode defaults to 1 until setup information is available.
function isDeviceOff(setup) {
    return Number((setup || {}).devmode ?? 1) === 0
}

// Keep the ControlTypes state sent to S2 synchronized with the combined
// communication, temperature and devmode block state. Return a message only
// when the advertised state actually changes.
function controlStateTransition(
    communicationDisabled,
    temperatureBlocked,
    deviceOff
) {
    const controlBlocked =
        communicationDisabled ||
        temperatureBlocked ||
        deviceOff
    const advertisedOff = flow.get('mypv_control_advertised_off') === true

    if (controlBlocked && !advertisedOff) {
        flow.set('mypv_control_advertised_off', true)
        return {
            topic: 'ControlTypes',
            payload: { isControllable: false }
        }
    }

    if (!controlBlocked && advertisedOff) {
        flow.set('mypv_control_advertised_off', false)
        return {
            topic: 'ControlTypes',
            payload: { isControllable: true }
        }
    }

    return null
}

const temperatureBlocked = flow.get('mypv_temperature_blocked') === true
const currentSetup = flow.get('mypv_setup') || {}
const currentDeviceOff = isDeviceOff(currentSetup)

if (!requestSucceeded) {
    // A setup.jsn failure is handled exactly like failures on the other My-PV
    // HTTP endpoints. Isolated ECONNREFUSED errors are harmless; OMBC is only
    // disabled after 30 seconds without ANY successful My-PV HTTP exchange.
    const previousCommunicationDisabled = flow.get('mypv_ombc_disabled') === true
    const communicationDisabled = communicationTimedOut(now)
    flow.set('mypv_ombc_disabled', communicationDisabled)

    if (communicationDisabled && !previousCommunicationDisabled) {
        node.warn('No successful My-PV communication for 30 seconds; OMBC disabled')
    }

    const reference =
        Number(flow.get('mypv_last_comm_success')) ||
        Number(flow.get('mypv_comm_watch_started')) ||
        now
    const secondsWithoutSuccess = Math.max(
        0,
        Math.floor((now - reference) / 1000)
    )

    node.status({
        shape: 'ring',
        fill: communicationDisabled ? 'red' : currentDeviceOff ? 'grey' : 'yellow',
        text: communicationDisabled
            ? 'My-PV offline for 30+ s; OMBC off'
            : currentDeviceOff
              ? 'Device off (devmode 0); OMBC off'
              : 'setup.jsn error; last communication ' +
                secondsWithoutSuccess +
                ' s ago'
    })

    return controlStateTransition(
        communicationDisabled,
        temperatureBlocked,
        currentDeviceOff
    )
}

// Any successful My-PV HTTP response immediately proves that the device is
// reachable. Refresh the single shared communication-health timestamp before
// parsing the payload: malformed setup data is a data-quality issue, not a
// communication outage.
flow.set('mypv_last_comm_success', now)
flow.set('mypv_comm_watch_started', now)
flow.set('mypv_ombc_disabled', false)

let setup

try {
    setup =
        typeof msg.payload === 'string'
            ? JSON.parse(msg.payload)
            : msg.payload
} catch (error) {
    node.status({
        shape: 'ring',
        fill: currentDeviceOff ? 'grey' : 'yellow',
        text: currentDeviceOff
            ? 'Device off (devmode 0); OMBC off'
            : 'My-PV reachable; setup.jsn invalid'
    })

    return controlStateTransition(
        false,
        temperatureBlocked,
        currentDeviceOff
    )
}

if (!setup || typeof setup !== 'object') {
    node.status({
        shape: 'ring',
        fill: currentDeviceOff ? 'grey' : 'yellow',
        text: currentDeviceOff
            ? 'Device off (devmode 0); OMBC off'
            : 'My-PV reachable; setup.jsn invalid'
    })

    return controlStateTransition(
        false,
        temperatureBlocked,
        currentDeviceOff
    )
}

// Keep the complete setup response available for the temperature gate and UI.
// If the device did not provide devmode, default it to 1. This matches the
// request-side startup default while preserving any explicit device value.
if (setup.devmode === undefined || setup.devmode === null || setup.devmode === '') {
    setup.devmode = 1
}

flow.set('mypv_setup', setup)

const deviceOff = isDeviceOff(setup)

// setup.jsn is authoritative for devmode. Therefore a successful refresh can
// immediately remove or restore OMBC when devmode changes.
const controlMessage = controlStateTransition(
    false,
    temperatureBlocked,
    deviceOff
)

// My-PV reports these temperature settings in tenths of a degree Celsius.
const targetTemperature = Number(setup.ww1target) / 10
const hysteresis = Number(setup.ww_targ_h) / 10

if (!Number.isFinite(targetTemperature)) {
    node.status({
        shape: 'ring',
        fill: deviceOff ? 'grey' : 'yellow',
        text: deviceOff
            ? 'Device off (devmode 0); OMBC off'
            : 'My-PV reachable; no temperature target configured'
    })
    return controlMessage
}

node.status({
    shape: 'dot',
    fill: deviceOff ? 'grey' : temperatureBlocked ? 'yellow' : 'green',
    text: deviceOff
        ? 'Device off (devmode 0); OMBC off'
        : 'Temp gate: ' +
          targetTemperature +
          ' °C +/- ' +
          (Number.isFinite(hysteresis) ? hysteresis : 0) +
          ' °C'
})

return controlMessage

// AC-Thor 9S operation state reported by data.jsn.

// Language code used for state labels, supported: en, de, es, fr, it, nl
const LANGUAGE_CODE = "en";

const data = flow.get('mypv_data') || {}
const setup = flow.get('mypv_setup') || {}

// Do not update indicators until both data and setup information are available.
if (Object.keys(data).length === 0 || Object.keys(setup).length === 0) {
    return null
}

function numberOrNull(value) {
    if (value === undefined || value === null || value === '') {
        return null
    }

    const number = Number(value)
    return Number.isFinite(number) ? number : null
}

const numberOrZero = value =>
    Number.isFinite(Number(value)) ? Number(value) : 0

const infoStateLabels = {
    en: [
        'Standby',
        'Heating',
        'Boost heating',
        'Heating finished',
        'No communication',
        'Error',
        'Device blocked',
        'Unknown'
    ],

    de: [
        'Standby',
        'Heizen',
        'Heizen Sicherstellung',
        'Heizen beendet',
        'Keine Verbindung',
        'Fehler',
        'Sperrzeit aktiv',
        'Unbekannt'
    ],

    es: [
        'Standby',
        'Calentamiento',
        'Boost calentamiento',
        'El calentamiento se acabó',
        'No hay conexión',
        'Error',
        'Tiempo de parada activo',
        'Desconocido'
    ],

    fr: [
        'Standby',
        'Chauffage',
        'Sécurisation chauffage',
        'Chauffage terminé',
        'Pas de connexion',
        'Erreur',
        'Blocage activé',
        'Inconnu'
    ],

    it: [
        'Standby',
        'Riscaldamento',
        'Assicurazione del riscaldamento',
        'Riscaldamento terminato',
        'Nessuna connessione',
        'Errore',
        'Tempo di blocco attivo',
        'Sconosciuto'
    ],

    nl: [
        'Stand-by',
        'Verwarmen',
        'Verwarmen (zekerstelling)',
        'Verwarmen beëindigd',
        'Geen verbinding',
        'Fout',
        'Blokkeertijd actief',
        'Onbekend'
    ]
}

const rawInfoState = numberOrNull(data.screen_mode_flag)
const infoState = rawInfoState === null ? 7 : rawInfoState
const operationState = infoStateLabels[LANGUAGE_CODE][infoState] || infoStateLabels[LANGUAGE_CODE][7]

// My-PV reports temperatures in tenths of a degree Celsius.
const currentTemperatureRaw = numberOrNull(data.temp1)
const targetTemperatureRaw = numberOrNull(setup.ww1target)

// Warm-water minimum-temperature assurance:
// wws_bstmode = 0 means disabled.
// wws_acthor_bsttemp is the minimum temperature in tenths of a degree.
const minimumTemperatureRaw = numberOrNull(setup.wws_acthor_bsttemp)
const minimumTemperatureEnabled =
    numberOrNull(setup.wws_bstmode) !== null &&
    Number(setup.wws_bstmode) !== 0 &&
    minimumTemperatureRaw !== null

const minTemp = minimumTemperatureEnabled
    ? minimumTemperatureRaw / 10
    : 20
const maxTemp = targetTemperatureRaw === null
    ? 90
    : targetTemperatureRaw / 10
const currentTemp = currentTemperatureRaw === null
    ? null
    : currentTemperatureRaw / 10

const l1Power =
    numberOrZero(data.power1_solar) +
    numberOrZero(data.power1_grid)
const l2Power =
    numberOrZero(data.power2_solar) +
    numberOrZero(data.power2_grid)
const l3Power =
    numberOrZero(data.power3_solar) +
    numberOrZero(data.power3_grid)
const sumPower = l1Power + l2Power + l3Power

node.status({
    shape: 'dot',
    fill: 'green',
    text: `${currentTemp} / ${maxTemp} °C | ${sumPower} W | ${operationState}`
})

return [
    {
        payload: {
            '/SwitchableOutput/output_1/State':
                setup.devmode !== undefined && setup.devmode !== null
                    ? setup.devmode
                    : 1
        }
    },
    {
        payload: {
            '/GenericInput/0/Value': currentTemp,
            '/GenericInput/0/Settings/RangeMin': minTemp,
            '/GenericInput/0/Settings/RangeMax': maxTemp
        }
    },
    {
        payload: {
            '/GenericInput/0/Value': sumPower
        }
    },
    {
        payload: {
            '/GenericInput/0/Value': infoState,
            '/GenericInput/0/Settings/Labels': infoStateLabels[LANGUAGE_CODE]
        }
    },
    {
        payload: {
            '/Temperature': currentTemp
        }
    },
]

const HEARTBEAT_INTERVAL_MS = 3000
const COMMUNICATION_TIMEOUT_MS = 30000

// data.jsn and this function are triggered by the same 2-second inject. A due
// heartbeat therefore must NOT be sent immediately, otherwise two HTTP requests
// would reach the small My-PV CPU at almost exactly the same time.
//
// Wait for the current data.jsn request to finish and then leave a short quiet
// period before sending control.html. If telemetry is unusually slow, skip this
// heartbeat rather than stacking another request onto a busy device.
const DATA_CHECK_INTERVAL_MS = 40
const MAX_WAIT_FOR_DATA_MS = 500
const POST_DATA_GAP_MS = 180
const MAX_TOTAL_DELAY_MS = 750

const now = Date.now()

// Record the start of this telemetry cycle for diagnostics.
flow.set('mypv_last_data_poll_tick', now)

const setpoint = flow.get('mypv_setpoint')
if (!setpoint || typeof setpoint !== 'object') {
    return null
}

const lastSent = Number(setpoint.lastSent) || 0
if (now - lastSent < HEARTBEAT_INTERVAL_MS) {
    return null
}

// Prevent more than one delayed heartbeat from being scheduled at a time.
// The timestamp also makes the guard self-recover if Node-RED was interrupted
// while a delayed heartbeat was pending.
const pendingSince = Number(context.get('heartbeatPendingSince')) || 0
if (pendingSince > 0 && now - pendingSince < MAX_TOTAL_DELAY_MS + 1000) {
    return null
}
context.set('heartbeatPendingSince', now)

const startingDataCycle = Number(flow.get('mypv_data_cycle')) || 0
const scheduledAt = now
const heartbeatMsg = { ...msg }

function clearPending() {
    context.set('heartbeatPendingSince', 0)
}

function communicationTimedOut(time) {
    let reference = Number(flow.get('mypv_last_comm_success'))

    if (!Number.isFinite(reference) || reference <= 0) {
        reference = Number(flow.get('mypv_comm_watch_started'))

        if (!Number.isFinite(reference) || reference <= 0) {
            reference = time
            flow.set('mypv_comm_watch_started', reference)
        }
    }

    return time - reference >= COMMUNICATION_TIMEOUT_MS
}

function trySendHeartbeat() {
    const currentTime = Date.now()
    const elapsed = currentTime - scheduledAt
    const currentDataCycle = Number(flow.get('mypv_data_cycle')) || 0

    // The current data.jsn request has not completed yet. Give it a short time
    // to finish, but never stack a SET request behind a slow telemetry request.
    if (currentDataCycle <= startingDataCycle) {
        if (elapsed >= MAX_WAIT_FOR_DATA_MS) {
            clearPending()
            return
        }

        setTimeout(trySendHeartbeat, DATA_CHECK_INTERVAL_MS)
        return
    }

    const lastDataCompletion = Number(flow.get('mypv_last_data_completion')) || 0
    const quietTime = currentTime - lastDataCompletion

    // Give the embedded HTTP server a short breathing period after data.jsn.
    if (quietTime < POST_DATA_GAP_MS) {
        const remainingGap = POST_DATA_GAP_MS - quietTime

        if (elapsed + remainingGap > MAX_TOTAL_DELAY_MS) {
            clearPending()
            return
        }

        setTimeout(trySendHeartbeat, remainingGap)
        return
    }

    // Do not send a stale heartbeat if a new S2 instruction has already caused
    // a more recent SET attempt while this heartbeat was waiting.
    const latestSetpoint = flow.get('mypv_setpoint')
    if (!latestSetpoint || typeof latestSetpoint !== 'object') {
        clearPending()
        return
    }

    const latestLastSent = Number(latestSetpoint.lastSent) || 0
    if (latestLastSent > scheduledAt) {
        clearPending()
        return
    }

    const setup = flow.get('mypv_setup') || {}
    const deviceOff = Number(setup.devmode ?? 1) === 0

    // devmode = 0 is a hard pause for control traffic. Do not send any
    // control.html request while the My-PV device is switched off. Keep the
    // stored S2 setpoint unchanged so it can resume when devmode returns to 1.
    if (deviceOff) {
        clearPending()
        return
    }

    const temperatureBlocked = flow.get('mypv_temperature_blocked') === true
    const communicationDisabled = communicationTimedOut(currentTime)

    // For communication timeout or an active temperature gate, send 0 W as a
    // safe heartbeat/probe. devmode = 0 is handled above by sending nothing.
    const desiredPower = Number(latestSetpoint.power) || 0
    const heartbeatPower =
        communicationDisabled || temperatureBlocked
            ? 0
            : desiredPower

    // Store the attempt time before sending. With the 2-second trigger and the
    // 3-second minimum interval, normal heartbeat spacing is about 4 seconds,
    // comfortably inside the intended 3-5 second range.
    latestSetpoint.lastSent = currentTime
    flow.set('mypv_setpoint', latestSetpoint)

    heartbeatMsg.payload = heartbeatPower
    heartbeatMsg.mypvHeartbeat = true

    // A heartbeat is not a new S2 instruction and must never generate a
    // ModeConfirmation in the response handler.
    delete heartbeatMsg.modeConfirmationPayload

    clearPending()
    node.send(heartbeatMsg)
}

// Start checking shortly after the simultaneous data.jsn request was launched.
setTimeout(trySendHeartbeat, DATA_CHECK_INTERVAL_MS)
return null
